    <!-- 
      Container do Slider
      Usamos 'relative' para posicionar os botões de navegação
    -->
    <div class="relative">
        
        <!-- 
          O 'Track' (trilho) que contém os slides.
          - 'flex', 'overflow-x-auto', 'snap-x', 'scroll-smooth' criam o slider.
          - 'scrollbar-hide' é a classe CSS que esconde a barra de scroll.
        -->
        <div id="testimony-slider-track" 
             class="flex overflow-x-auto scroll-smooth snap-x snap-mandatory scrollbar-hide">
            
            <?php 
            // echo '<!-- Debug Start -->';
            // echo '<!-- Checking option: -->';
            // var_dump(get_field('testemunhos', 'option'));
            // echo '<!-- Checking options: -->';
            // var_dump(get_field('testemunhos', 'options'));
            // echo '<!-- Debug End -->';
            if( have_rows('testemunhos', 'option') ):
                while( have_rows('testemunhos', 'option') ): the_row();
                    
                    // Pegar os dados dos sub-campos
                    $imagem = get_sub_field('imagem_testemunho');
                    $texto = get_sub_field('texto_testemunho');
                    $autor = get_sub_field('autor_testemunho');
                    $cargo = get_sub_field('cargo_testemunho');
            ?>
                <!-- 
                  Cada Slide Individual (o seu .wrapper-item)
                  - 'w-full': Ocupa 100% da largura do container.
                  - 'flex-shrink-0': IMPEDE que o slide encolha.
                  - 'snap-center': Força o slide a centralizar no "snap".
                -->
                <div class="wrapper-item w-full flex-shrink-0 snap-center text-center px-4 lg:px-20">
                    
                    <?php if($imagem): ?>
                        <img src="<?php echo esc_url($imagem['url']); ?>" 
                             alt="<?php echo esc_attr($imagem['alt']); ?>"
                             class="w-32 h-32 rounded-full object-cover mx-auto mb-8">
                    <?php endif; ?>

                    <?php if($texto): ?>
                        <!-- 
                          Estilização do Figma: 
                          serif, itálico, texto grande, cor escura 
                        -->
                        <p class="text-2xl lg:text-3xl italic font-serif text-brand-azul-escuro mb-6">
                            "<?php echo esc_html($texto); ?>"
                        </p>
                    <?php endif; ?>
                    
                    <?php if($autor): ?>
                        <!-- 
                          Estilização do Figma: 
                          sans-serif, maiúsculas, espaçamento, cor café
                        -->
                        <strong class="block text-sm uppercase font-sans tracking-wider text-brand-cafe mt-4">
                            <?php echo esc_html($autor); ?>
                        </strong>
                    <?php endif; ?>

                    <?php if($cargo): ?>
                        <!-- 
                          Estilização do Figma: 
                          sans-serif, pequeno, cor azul-escuro com opacidade
                        -->
                        <small class="block text-sm font-sans text-brand-azul-escuro/70">
                            <?php echo esc_html($cargo); ?>
                        </small>
                    <?php endif; ?>

                </div><!-- .wrapper-item -->
            
            <?php 
                endwhile;
            endif; 
            ?>
        </div> <!-- #testimony-slider-track -->

        <!-- 
          Botões de Navegação 
          Posicionados de forma absoluta em relação ao <div class="relative">
        -->
        <button id="testimony-prev-btn" aria-label="Testemunho Anterior"
                class="absolute top-1/2 left-0 -translate-y-1/2 text-brand-marrom hover:opacity-50 transition-opacity">
            <svg class="w-10 h-10" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="2" stroke="#27363F">
                <path stroke-linecap="round" stroke-linejoin="round" d="M15.75 19.5 8.25 12l7.5-7.5" />
            </svg>
        </button>
        <button id="testimony-next-btn" aria-label="Próximo Testemunho"
                class="absolute top-1/2 right-0 -translate-y-1/2 text-brand-marrom hover:opacity-50 transition-opacity">
            <svg class="w-10 h-10" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke-width="2" stroke="#27363F">
                <path stroke-linecap="round" stroke-linejoin="round" d="m8.25 4.5 7.5 7.5-7.5 7.5" />
            </svg>
        </button>

    </div><!-- .relative -->
